NO_BREACH_PRE = r'(?P<anchor>\b(?:A|Any|The)?[ \t]*(?P<behavior>disclos(?:e|es|ed|ing|ure)|shar(?:e|es|ed|ing))\b(?:[ \t]+(?P<condition>(?:by|of|in|when|if|as|under|pursuant)\b[^.;:\r\n]{0,260}?))?[ \t]+(?P<head>(?:shall[ \t]+not[ \t]+have[ \t]+breached|shall[ \t]+not[ \t]+be[ \t]+(?:deemed|considered)(?:[ \t]+to[ \t]+be)?[ \t]+(?:in[ \t]+|a[ \t]+)?breach|(?:shall|will|does|did)[ \t]+not[ \t]+constitute[ \t]+(?:a[ \t]+)?breach))\b[^.;\r\n]*(?:[:.;]|$))'


def _emit(records, match, kind, action, condition_names, reference_names, clear_overrides):
    groups = match.groupdict()
    anchor = groups.get('anchor')
    head = groups.get('head')
    behavior = groups.get('behavior')
    if not anchor or not head or not behavior:
        return
    conditions = []
    for name in condition_names:
        value = groups.get(name)
        if value:
            conditions.append(value)
    references = []
    for name in reference_names:
        value = groups.get(name)
        if value:
            references.append(value)
    record = {'start': match.start('anchor'), 'end': match.end('anchor'), 'quote': anchor, 'head': head, 'behavior': behavior, 'kind': kind, 'action': action, 'conditions': conditions, 'references': references, 'clear_overrides': clear_overrides}
    if record not in records:
        records.append(record)


